import { arabicSpellingForMalayalam } from "./arabicLoanwords.ts";
import { transliterateMalayalamToArabic } from "./malayalamToArabic.ts";

/**
 * The Arabi-Malayalam alphabet, generated by running the converter itself over
 * Malayalam letters, so the guide can never disagree with what the keyboard
 * types. Only the Malayalam letters, their sounds and the page layout are
 * written out by hand here; every Arabi-Malayalam spelling comes from the converter.
 */

const SUKUN = "ْ";
const VIRAMA = "്";
/** Arabic letters in the basic Arabic block; anything else was added for Malayalam. */
const BASIC_ARABIC = /[ء-ي]/u;

export interface Letter {
  /** Malayalam letter. */
  ml: string;
  /** Sound, in a simple Roman spelling. */
  sound: string;
  /** Arabi-Malayalam spelling, without vowel or sukun. */
  arabi: string;
  /** True when the spelling uses a letter that basic Arabic does not have. */
  extra: boolean;
  /** Unicode code points of the added letters, e.g. ["U+06BF"]. */
  addedCodePoints: string[];
}

export interface LetterGroup {
  title: string;
  letters: Letter[];
}

const codePoint = (char: string) =>
  `U+${char.codePointAt(0)!.toString(16).toUpperCase().padStart(4, "0")}`;

function describeLetter(ml: string, sound: string, arabi: string): Letter {
  const added = [...arabi].filter((char) => !BASIC_ARABIC.test(char));
  return {
    ml,
    sound,
    arabi,
    extra: added.length > 0,
    addedCodePoints: [...new Set(added)].map(codePoint),
  };
}

const arabi = (ml: string) => transliterateMalayalamToArabic(ml).normalize("NFC");

/** A consonant without its vowel: the converter writes it with sukun, which is dropped here. */
const bareConsonant = (ml: string) => arabi(ml + VIRAMA).replaceAll(SUKUN, "");

