/** Arabic-origin words keep their Arabic spelling; the converter's letter-by-letter reading is shown beside it. */
const LOANWORD_SAMPLES: Array<[ml: string, meaning: string]> = [
  ["ഖുർആൻ", "Quran"],
  ["സ്വലാത്ത്", "prayer; blessings on the Prophet"],
  ["റസൂൽ", "messenger"],
  ["മസ്ജിദ്", "mosque"],
  ["ഹദീസ്", "hadith"],
  ["റമദാൻ", "Ramadan"],
  ["ഖബർ", "grave"],
  ["ശൈഖ്", "sheikh"],
  ["ഫാത്തിമ", "Fathima"],
  ["ആയിഷ", "Aisha"],
  ["ഖിലാഫത്ത്", "caliphate"],
  ["മുഹ്യിദ്ദീൻ", "Muhyiddin"],
];

export interface LoanwordSample {
  ml: string;
  meaning: string;
  /** The Arabic spelling the keyboard uses. */
  spelling: string;
  /** What reading the Malayalam letter by letter would give instead. */
  letterByLetter: string;
}

export const LOANWORDS: LoanwordSample[] = LOANWORD_SAMPLES.flatMap(([ml, meaning]) => {
  const spelling = arabicSpellingForMalayalam(ml);
  return spelling ? [{ ml, meaning, spelling, letterByLetter: arabi(ml) }] : [];
});
